package com.example.shelflife;

import android.content.Context;
import java.time.LocalDate;
import java.util.*;
public class StockRepository {
 final AppDatabase db;final ProductDao dao;final long staffId;
 public StockRepository(Context c){this(AppDatabase.get(c),Auth.session(c));}
 public StockRepository(AppDatabase db,long id){this.db=db;dao=db.productDao();staffId=id;}
 private Staff staff(){Staff s=dao.staff(staffId);if(s==null)throw new IllegalArgumentException("Sign in again");return s;}
 private Product get(long id){Product p=dao.get(id);if(p==null)throw new IllegalArgumentException("Batch no longer available");return p;}
 private void active(Product p){if(p.archived)throw new IllegalArgumentException("Restore this product first");}
 private static String clean(String s){return s==null?"":s.trim();}
 private void identity(Product p,String originalSku){
  canonicalCategory(p);Validators.product(p);p.name=clean(p.name);p.sku=clean(p.sku);p.barcode=clean(p.barcode);p.brand=clean(p.brand);p.unit=clean(p.unit);
  for(Product other:dao.getAll())if(!other.sku.equals(originalSku)&&other.sku.equals(p.sku))throw new IllegalArgumentException("SKU already exists. Use Add batch for the existing product");
  if(!p.barcode.isEmpty())for(Product other:dao.getAll())if(!other.sku.equals(originalSku)&&p.barcode.equals(other.barcode))throw new IllegalArgumentException("Barcode belongs to another product, including archived stock");
 }
 public long receive(Product p,boolean existing,boolean acknowledged){return receiveCore(p,existing,acknowledged,false);}
 public long receiveQuantities(Product p,boolean existing,boolean acknowledged){return receiveCore(p,existing,acknowledged,true);}
 private long receiveCore(Product p,boolean existing,boolean acknowledged,boolean explicit){return db.runInTransaction(()->{
  staff();validateReference(p,p.id);canonicalCategory(p);Validators.product(p);List<Product> same=dao.sku(clean(p.sku));
  if(existing){if(same.isEmpty())throw new IllegalArgumentException("Product no longer exists");Product master=same.get(0);active(master);p.productId=master.productId;p.measurementValue=master.measurementValue;p.measurementUnit=master.measurementUnit;p.variation=master.variation;p.description=master.description;p.packSize=master.packSize;p.photoPath=master.photoPath;p.name=master.name;p.barcode=master.barcode;p.brand=master.brand;for(Product sibling:same){sibling.category=p.category;dao.update(sibling);}p.unit=master.unit;p.lowStock=master.lowStock;}
  else {if(!same.isEmpty())throw new IllegalArgumentException("SKU already exists. Add a batch to that product");identity(p,"");p.productId=null;}
  Rules.quantity(Double.toString(p.quantity),true);p.batchNo=clean(p.batchNo);p.location=clean(p.location);
  if(p.quantity>0&&p.location.isEmpty())throw new IllegalArgumentException("Storage location is required");
  if(!Arrays.asList("Expiry","Best Before","Unknown").contains(p.dateType))throw new IllegalArgumentException("Choose the date-label type");
  if("Unknown".equals(p.dateType))p.expiryDate=null;else if(p.expiryDate==null)throw new IllegalArgumentException("Choose the printed date or select Unknown");
  if(p.receivedDay>LocalDate.now().toEpochDay())throw new IllegalArgumentException("Received date cannot be in the future");
  if(p.expiryDate!=null&&p.expiryDate<LocalDate.now().toEpochDay()&&!acknowledged)throw new IllegalArgumentException("Acknowledge the past-date stock warning");
  p.archived=false;p.deleted=false;CatalogProduct catalog=CatalogProduct.from(p);if(existing){dao.update(catalog);}else{p.productId=dao.insert(catalog);}if(!explicit)p.received=p.quantity;validateBatchAmounts(p);rememberOptions(p);p.id=dao.insert(p);if(p.received>0)movement(p,p.received,"Stock In","",null);if(p.quantity<p.received)movement(p,Rules.rounded(p.quantity-p.received),"Quantity correction","Remaining stock recorded at registration",null);return p.id;
 });}
 public void edit(Product changes){db.runInTransaction(()->{staff();Product old=get(changes.id);identity(changes,old.sku);rememberOptions(changes);if(!old.sku.equals(changes.sku))throw new IllegalArgumentException("SKU is fixed after creation");
  for(Product p:dao.sku(old.sku)){p.measurementValue=changes.measurementValue;p.measurementUnit=changes.measurementUnit;p.unit=changes.unit;p.variation=changes.variation;p.description=changes.description;p.packSize=changes.packSize;p.photoPath=changes.photoPath;p.name=changes.name;p.barcode=changes.barcode;p.brand=changes.brand;p.category=changes.category;p.lowStock=changes.lowStock;dao.update(p);}changes.productId=old.productId;changes.archived=old.archived;changes.deleted=old.deleted;dao.update(CatalogProduct.from(changes));
 });}
 public void out(long id,double q,String reason,String note){db.runInTransaction(()->{staff();Product p=get(id);active(p);if(!Arrays.asList("Sold","Expired","Damaged","Returned to Supplier").contains(reason))throw new IllegalArgumentException("Choose a stock-out reason");Rules.stockOut(q,p.quantity,p.expiryDate,p.dateType,reason,LocalDate.now());p.quantity=Rules.rounded(p.quantity-q);dao.update(p);movement(p,-q,reason,note,null);});}
 private void movement(Product p,double delta,String reason,String note,Long reversal){Staff s=staff();StockMovement m=new StockMovement();m.batchId=p.id;m.staffId=s.id;m.unit=p.unit;m.staffName=s.name;m.delta=delta;m.reason=reason;m.note=note;m.time=System.currentTimeMillis();m.reversalOf=reversal;dao.insert(m);}
 public void reverse(long id,String note){db.runInTransaction(()->{staff();StockMovement m=dao.movement(id);if(m==null||"Quantity correction".equals(m.reason)||m.reversalOf!=null||dao.reversed(id)>0)throw new IllegalArgumentException("Movement cannot be reversed again");if(clean(note).isEmpty())throw new IllegalArgumentException("Enter a correction reason");Product p=get(m.batchId);active(p);if(m.unit!=null&&!m.unit.equals(p.unit))throw new IllegalArgumentException("This movement used "+m.unit+". Correct the unit first before reversal.");double next=Rules.rounded(p.quantity-m.delta);if(next<0||next>p.received)throw new IllegalArgumentException("Reverse dependent movements first");p.quantity=next;dao.update(p);movement(p,-m.delta,"Reversal",note,id);});}
 public void archive(String sku,boolean archived){setStatus(sku,archived,false);}
 public void delete(String sku){setStatus(sku,true,true);}
 private void setStatus(String sku,boolean archived,boolean deleted){db.runInTransaction(()->{staff();List<Product> group=dao.sku(sku);if(group.isEmpty())throw new IllegalArgumentException("Product no longer exists");for(Product p:group){p.archived=archived;p.deleted=deleted;dao.update(p);}CatalogProduct c=dao.catalog(sku);c.archived=archived;c.deleted=deleted;dao.update(c);});}
 private void validateReference(Product p,long exceptId){p.stockReference=clean(p.stockReference);if(p.stockReference.isEmpty()||p.stockReference.length()>40||p.stockReference.matches(".*[\\p{Cntrl}].*"))throw new IllegalArgumentException("Enter a batch reference of 1–40 readable characters");if(dao.duplicateBatch(clean(p.sku),p.stockReference,exceptId)>0)throw new IllegalArgumentException("This batch reference already exists for this product. Choose another reference.");}
 private void canonicalCategory(Product p){String key=CategorySuggestions.key(p.category);if(!CategorySuggestions.inventoryVisible(p.category))throw new IllegalArgumentException("Choose an available category");for(String option:CategorySuggestions.choices(dao.categories()))if(CategorySuggestions.key(option).equals(key)){p.category=option;return;}p.category=CategorySuggestions.clean(p.category);}
 private void rememberOptions(Product p){if(p.category!=null&&!p.category.trim().isEmpty())dao.remember(new SavedOption("category",p.category.trim()));if(p.measurementUnit!=null&&!p.measurementUnit.trim().isEmpty())dao.remember(new SavedOption("unit",p.measurementUnit.trim()));}
 private static void validateBatchAmounts(Product p){Rules.quantity(Double.toString(p.received),true);Rules.quantity(Double.toString(p.quantity),true);if(p.quantity>p.received)throw new IllegalArgumentException("Quantity remaining cannot exceed quantity received");}
 public long register(Product p,boolean acknowledged){return registerCore(p,acknowledged,false);}
 public long registerQuantities(Product p,boolean acknowledged){return registerCore(p,acknowledged,true);}
 private long registerCore(Product p,boolean acknowledged,boolean explicit){return db.runInTransaction(()->{canonicalCategory(p);SkuGenerator.requireReady(p.barcode,p.name,p.category,p.brand,p.measurementValue,p.measurementUnit,p.variation);for(CatalogProduct c:dao.catalogAll())if(clean(c.name).equalsIgnoreCase(clean(p.name))&&clean(c.brand).equalsIgnoreCase(clean(p.brand))&&clean(c.category).equalsIgnoreCase(clean(p.category))&&clean(c.packSize).equalsIgnoreCase(clean(p.packSize))&&clean(c.variation).equalsIgnoreCase(clean(p.variation)))throw new IllegalArgumentException("This product is already registered as "+c.sku+". Find it in Inventory and use Add stock or Restore.");String base=SkuGenerator.generate(p.name,p.category,p.brand,p.measurementValue,p.variation);String unique=base;int suffix=2;while(dao.catalog(unique)!=null)unique=base+"-"+suffix++;p.sku=unique;return receiveCore(p,false,acknowledged,explicit);});}
 public void editFull(Product changes,boolean acknowledged){db.runInTransaction(()->{staff();Product old=get(changes.id);validateReference(changes,changes.id);validateBatchAmounts(changes);Rules.quantity(Double.toString(changes.quantity),true);if(changes.quantity>0&&clean(changes.location).isEmpty())throw new IllegalArgumentException("Storage location is required");if(!Arrays.asList("Expiry","Best Before","Unknown").contains(changes.dateType))throw new IllegalArgumentException("Choose date type");if("Unknown".equals(changes.dateType))changes.expiryDate=null;else if(changes.expiryDate==null)throw new IllegalArgumentException("Choose printed date");if(changes.receivedDay>LocalDate.now().toEpochDay())throw new IllegalArgumentException("Received date cannot be in the future");if(changes.expiryDate!=null&&changes.expiryDate<LocalDate.now().toEpochDay()&&!Objects.equals(old.expiryDate,changes.expiryDate)&&!acknowledged)throw new IllegalArgumentException("Acknowledge the past-date label");
 edit(changes);Product batch=get(old.id);double delta=Rules.rounded(changes.quantity-old.quantity);batch.quantity=changes.quantity;batch.received=changes.received;batch.stockReference=changes.stockReference;batch.batchNo=clean(changes.batchNo);batch.location=clean(changes.location);batch.expiryDate=changes.expiryDate;batch.dateType=changes.dateType;batch.receivedDay=changes.receivedDay;dao.update(batch);if(!Objects.equals(old.expiryDate,batch.expiryDate)||!Objects.equals(old.dateType,batch.dateType))dao.clearReminders(batch.id);if(delta!=0||old.received!=batch.received)movement(batch,delta,"Quantity correction","Edited batch quantity from "+Rules.qty(old.quantity)+" to "+Rules.qty(batch.quantity)+"; received "+Rules.qty(old.received)+" to "+Rules.qty(batch.received),null);
 });}
 public List<String> permanentlyDelete(String sku){return db.runInTransaction(()->{staff();List<Product> group=dao.sku(sku);if(group.isEmpty())throw new IllegalArgumentException("Product no longer exists");Set<String> photos=new HashSet<>();for(Product batch:group){if(!batch.deleted)throw new IllegalArgumentException("Move the product to Deleted first");if(batch.photoPath!=null)photos.add(batch.photoPath);}dao.deleteReminders(sku);dao.deleteMovements(sku);dao.deleteBatches(sku);dao.deleteCatalog(sku);photos.removeIf(path->dao.photoReferences(path)>0||dao.staffPhotoReferences(path)>0);return new ArrayList<>(photos);});}
 public static Product fefo(List<Product> all,String sku){return all.stream().filter(p->p.sku.equals(sku)&&!p.archived&&p.quantity>0&&!("Expiry".equals(p.dateType)&&Expiry.daysLeft(p)<0)).min(Comparator.comparingLong(p->p.expiryDate==null?Long.MAX_VALUE:p.expiryDate)).orElse(null);}
 public void samples(){db.runInTransaction(()->{staff();if(!dao.getAll().isEmpty())throw new IllegalArgumentException("Sample data requires an empty inventory");String[] names={"DEMO · Canned Tuna","DEMO · Fresh Milk 1L","DEMO · Sliced Bread","DEMO · Orange Juice","DEMO · Biscuits","DEMO · Pechay"};String[] cats={"Canned Goods","Dairy and Eggs","Bread and Bakery","Beverages","Snacks and Biscuits","Fruits and Vegetables"};int[] days={7,1,-1,0,8,3};for(int i=0;i<names.length;i++){Product p=new Product(names[i],"DEMO-"+i,"DEMO-LOT",cats[i],i==5?2.5:24,i==5?null:LocalDate.now().plusDays(days[i]).toEpochDay());p.unit=i==5?"kg":"pieces";p.location=i==1?"Chiller":"Shelf A";p.dateType=i==5?"Unknown":i==4?"Best Before":"Expiry";receive(p,false,true);if(i==1){p.id=0;p.quantity=12;p.expiryDate=LocalDate.now().plusDays(3).toEpochDay();receive(p,true,true);}}});}
}
